for filename in html_files:
    filepath = os.path.join(base_dir, filename)
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Replace footer css
    # We locate /* ── FOOTER ── */ rules and swap them
    css_match = re.search(r'/\* ── FOOTER ── \*/.*?(?=(/\* ── CART DRAWER ── \*/|/\* ── CART ── \*/))', content, re.DOTALL)
    if css_match:
        content = content.replace(css_match.group(0), '/* ── FOOTER ── */' + footer_css + '\n')
    else:
        # fallback, replace old style rules directly if comments are not exactly matched
        content = re.sub(r'footer\s*\{.*?\}.*?\.fdis\s*\{.*?\}', footer_css, content, flags=re.DOTALL)

    # Replace footer HTML
    # We find <footer> ... </footer> and replace it
    content = re.sub(r'<footer.*?>.*?</footer>', footer_html, content, flags=re.DOTALL)

    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"Updated footer in {filename}")

print("All footers updated successfully!")
